"""Cross-rule correlation of anomalous samples over a field lineage graph.

The public entry point is :func:`correlate_sample_anomalies`. It consumes a
batch of data quality check results (each carrying a rule id, dataset id,
field id, stable sample id, pass/fail flag and violating value) together
with a typed lineage graph of declared dataset/field nodes.

For each sample, violations triggered on the same field or on lineage
adjacent fields (one valid edge in either direction) are grouped into one
correlation event. Fields that merely belong to the same dataset without a
lineage edge between them stay in separate events.

Result/record problems raise :class:`InvalidCorrelationInputError`, graph
structure problems raise :class:`InvalidCorrelationGraphError` and a result
that references an undeclared dataset or field raises
:class:`UnknownCorrelationReferenceError`; the conflicting-duplicate case
raises a plain :class:`ValueError`. Every raised exception is a
:class:`ValueError`.
"""

from __future__ import annotations

from typing import Any, Dict, List, Optional, Set, Tuple

__all__ = [
    "correlate_sample_anomalies",
    "InvalidCorrelationInputError",
    "InvalidCorrelationGraphError",
    "UnknownCorrelationReferenceError",
]

RESULT_KEYS = frozenset(
    {"rule_id", "dataset_id", "field_id", "sample_id", "is_violation", "violating_value"}
)
FIELD_KEYS = frozenset({"dataset_id", "field_id"})
EDGE_KEYS = frozenset({"source", "target", "type"})
VALID_EDGE_TYPES = frozenset({"upstream", "downstream"})

# A field is identified by its (dataset_id, field_id) pair.
FieldId = Tuple[str, str]


class InvalidCorrelationInputError(ValueError):
    """The check-results batch is missing or malformed."""


class InvalidCorrelationGraphError(ValueError):
    """The lineage graph (``nodes``/``edges``) is missing or malformed."""


class UnknownCorrelationReferenceError(ValueError):
    """A check result references a dataset or field not declared in ``nodes``."""


def _identifier(value: Any, where: str) -> str:
    if not isinstance(value, str) or not value:
        raise InvalidCorrelationInputError(
            f"{where} must be a non-empty string"
        )
    return value


def _validate_results(results: Any) -> List[Dict[str, Any]]:
    if not isinstance(results, list):
        raise InvalidCorrelationInputError("results must be a list")

    clean: List[Dict[str, Any]] = []
    for index, result in enumerate(results):
        if not isinstance(result, dict):
            raise InvalidCorrelationInputError(
                f"results[{index}] must be an object"
            )
        keys = set(result)
        if keys != RESULT_KEYS:
            missing = sorted(RESULT_KEYS - keys)
            if missing:
                raise InvalidCorrelationInputError(
                    f"results[{index}] is missing keys: {missing}"
                )
            unknown = sorted(keys - RESULT_KEYS)
            raise InvalidCorrelationInputError(
                f"results[{index}] has unsupported keys: {unknown}"
            )

        rule_id = _identifier(result["rule_id"], f"results[{index}].rule_id")
        dataset_id = _identifier(
            result["dataset_id"], f"results[{index}].dataset_id"
        )
        field_id = _identifier(
            result["field_id"], f"results[{index}].field_id"
        )
        sample_id = _identifier(
            result["sample_id"], f"results[{index}].sample_id"
        )

        is_violation = result["is_violation"]
        # bool is a subclass of int; only JSON booleans are valid flags.
        if not isinstance(is_violation, bool):
            raise InvalidCorrelationInputError(
                f"results[{index}].is_violation must be a boolean"
            )

        clean.append(
            {
                "rule_id": rule_id,
                "dataset_id": dataset_id,
                "field_id": field_id,
                "sample_id": sample_id,
                "is_violation": is_violation,
                "violating_value": result["violating_value"],
            }
        )
    return clean


def _validate_nodes(nodes: Any) -> Set[FieldId]:
    if not isinstance(nodes, list):
        raise InvalidCorrelationGraphError("nodes must be a list")

    declared: Set[FieldId] = set()
    for index, node in enumerate(nodes):
        if not isinstance(node, dict):
            raise InvalidCorrelationGraphError(f"nodes[{index}] must be an object")
        keys = set(node)
        if keys != FIELD_KEYS:
            missing = sorted(FIELD_KEYS - keys)
            if missing:
                raise InvalidCorrelationGraphError(
                    f"nodes[{index}] is missing keys: {missing}"
                )
            unknown = sorted(keys - FIELD_KEYS)
            raise InvalidCorrelationGraphError(
                f"nodes[{index}] has unsupported keys: {unknown}"
            )

        dataset_id = _identifier(node["dataset_id"], f"nodes[{index}].dataset_id")
        field_id = _identifier(node["field_id"], f"nodes[{index}].field_id")
        pair = (dataset_id, field_id)
        if pair in declared:
            raise InvalidCorrelationGraphError(
                f"duplicate field node: {node!r}"
            )
        declared.add(pair)
    return declared


def _node_endpoint(endpoint: Any, where: str) -> FieldId:
    if not isinstance(endpoint, dict):
        raise InvalidCorrelationGraphError(f"{where} must be an object")
    keys = set(endpoint)
    if keys != FIELD_KEYS:
        missing = sorted(FIELD_KEYS - keys)
        if missing:
            raise InvalidCorrelationGraphError(
                f"{where} is missing keys: {missing}"
            )
        unknown = sorted(keys - FIELD_KEYS)
        raise InvalidCorrelationGraphError(
            f"{where} has unsupported keys: {unknown}"
        )
    dataset_id = _identifier(endpoint["dataset_id"], f"{where}.dataset_id")
    field_id = _identifier(endpoint["field_id"], f"{where}.field_id")
    return dataset_id, field_id


def _validate_edges(
    edges: Any, declared: Set[FieldId]
) -> Set[Tuple[FieldId, FieldId]]:
    """Validate typed edges and return the set of undirected field pairs.

    ``{"source": a, "target": b, "type": "downstream"}`` and
    ``{"source": b, "target": a, "type": "upstream"}`` describe the same
    data flow (a feeds b); repeating an edge with a contradictory type is
    rejected.
    """
    if not isinstance(edges, list):
        raise InvalidCorrelationGraphError("edges must be a list")

    # Maps an unordered pair to the canonical directed flow (source feeds
    # target), i.e. the downstream-typed orientation.
    flows: Dict[Tuple[FieldId, FieldId], FieldId] = {}

    for index, edge in enumerate(edges):
        if not isinstance(edge, dict):
            raise InvalidCorrelationGraphError(f"edges[{index}] must be an object")
        keys = set(edge)
        if keys != EDGE_KEYS:
            missing = sorted(EDGE_KEYS - keys)
            if missing:
                raise InvalidCorrelationGraphError(
                    f"edges[{index}] is missing keys: {missing}"
                )
            unknown = sorted(keys - EDGE_KEYS)
            raise InvalidCorrelationGraphError(
                f"edges[{index}] has unsupported keys: {unknown}"
            )

        source = _node_endpoint(edge["source"], f"edges[{index}].source")
        target = _node_endpoint(edge["target"], f"edges[{index}].target")
        edge_type = edge["type"]
        if edge_type not in VALID_EDGE_TYPES:
            raise InvalidCorrelationGraphError(
                f"edges[{index}].type must be one of "
                f"{sorted(VALID_EDGE_TYPES)}, got {edge_type!r}"
            )

        # Dangling endpoints: endpoints must reference declared field nodes.
        if source not in declared:
            raise InvalidCorrelationGraphError(
                f"edges[{index}].source is not a declared node: "
                f"{edge['source']!r}"
            )
        if target not in declared:
            raise InvalidCorrelationGraphError(
                f"edges[{index}].target is not a declared node: "
                f"{edge['target']!r}"
            )

        # upstream: source is fed by target, so the flow is target -> source.
        # downstream: source feeds target.
        upstream, downstream = (
            (target, source) if edge_type == "upstream" else (source, target)
        )
        pair = tuple(sorted((source, target)))

        previous = flows.get(pair)
        if previous is not None and previous != (upstream, downstream):
            raise InvalidCorrelationGraphError(
                f"contradictory duplicate edge between {source!r} and "
                f"{target!r}"
            )
        flows[pair] = (upstream, downstream)

    return set(flows)


def _build_adjacency(
    edge_pairs: Set[Tuple[FieldId, FieldId]]
) -> Dict[FieldId, Set[FieldId]]:
    adjacent: Dict[FieldId, Set[FieldId]] = {}
    for left, right in edge_pairs:
        adjacent.setdefault(left, set()).add(right)
        adjacent.setdefault(right, set()).add(left)
    return adjacent


def _merge_components(
    fields: List[FieldId], adjacent: Dict[FieldId, Set[FieldId]]
) -> List[Set[FieldId]]:
    """Partition ``fields`` so two fields share a component only when they
    are the same field or connected by a chain of valid lineage edges."""
    remaining = set(fields)
    components: List[Set[FieldId]] = []
    while remaining:
        seed = min(remaining)
        remaining.remove(seed)
        component = {seed}
        queue = [seed]
        while queue:
            current = queue.pop()
            for nxt in adjacent.get(current, ()):
                if nxt in remaining:
                    remaining.remove(nxt)
                    component.add(nxt)
                    queue.append(nxt)
        components.append(component)
    return components


def correlate_sample_anomalies(results: Any, lineage_graph: Any) -> Dict[str, Any]:
    """Group per-sample violations by lineage-adjacent fields.

    Inputs are fully read and validated before any output is produced;
    neither ``results`` nor ``lineage_graph`` is mutated.

    :param results: list of check-result objects, each with non-empty
        string ``rule_id``, ``dataset_id``, ``field_id`` and ``sample_id``,
        a boolean ``is_violation`` and a free-form ``violating_value``
        (``null`` when not applicable). The same ``(sample_id, rule_id)``
        pair may repeat only when every other field agrees, including the
        violating value.
    :param lineage_graph: ``{"nodes": [...], "edges": [...]}`` where nodes
        are ``{"dataset_id", "field_id"}`` objects and edges are
        ``{"source", "target", "type"}`` objects with ``type`` either
        ``"upstream"`` or ``"downstream"``. Both endpoints of every edge
        must be declared nodes; contradictory duplicate edges are rejected.
    :returns: ``{"events": [...]}``. Each event is
        ``{"sample_id", "rule_ids", "fields", "upstream_fields",
        "downstream_fields"}``. ``rule_ids`` are sorted; ``fields`` is the
        sorted set of fields carrying violations in the event;
        ``upstream_fields`` / ``downstream_fields`` are the sorted direct
        lineage neighbours of those fields (excluding the event fields
        themselves). Events are sorted by ``sample_id``. Samples without
        violations produce no event.
    :raises ValueError: :class:`InvalidCorrelationInputError`,
        :class:`InvalidCorrelationGraphError`,
        :class:`UnknownCorrelationReferenceError` or a plain
        :class:`ValueError` for a conflicting duplicate result.
    """
    clean_results = _validate_results(results)

    if not isinstance(lineage_graph, dict):
        raise InvalidCorrelationGraphError("lineage_graph must be an object")
    if "nodes" not in lineage_graph:
        raise InvalidCorrelationGraphError("lineage_graph is missing 'nodes'")
    if "edges" not in lineage_graph:
        raise InvalidCorrelationGraphError("lineage_graph is missing 'edges'")
    declared = _validate_nodes(lineage_graph["nodes"])
    edge_pairs = _validate_edges(lineage_graph["edges"], declared)

    # Deduplicate identical (sample, rule) results; reject content conflicts.
    # Keyed by (sample_id, rule_id) -> the canonical result dict.
    canonical: Dict[Tuple[str, str], Dict[str, Any]] = {}
    # sample_id -> rule_id -> field carrying the violation.
    violations_by_sample: Dict[str, Dict[str, FieldId]] = {}

    for result in clean_results:
        key = (result["sample_id"], result["rule_id"])
        previous = canonical.get(key)
        if previous is not None:
            if (
                previous["dataset_id"] != result["dataset_id"]
                or previous["field_id"] != result["field_id"]
                or previous["is_violation"] != result["is_violation"]
                or previous["violating_value"] != result["violating_value"]
            ):
                raise ValueError(
                    f"conflicting duplicate result for sample "
                    f"{result['sample_id']!r} and rule {result['rule_id']!r}"
                )
            continue
        canonical[key] = result

        field = (result["dataset_id"], result["field_id"])
        if result["is_violation"]:
            # Unknown dataset/field references are only relevant for
            # violations; pass results never enter an event.
            if field not in declared:
                raise UnknownCorrelationReferenceError(
                    f"result references an undeclared field: {result['dataset_id']!r}."
                    f"{result['field_id']!r}"
                )
            violations_by_sample.setdefault(result["sample_id"], {})[
                result["rule_id"]
            ] = field

    adjacent = _build_adjacency(edge_pairs)

    events: List[Dict[str, Any]] = []
    for sample_id in sorted(violations_by_sample):
        rule_fields = violations_by_sample[sample_id]
        fields = list(rule_fields.values())
        components = _merge_components(fields, adjacent)

        for component in components:
            rule_ids = sorted(
                rule_id
                for rule_id, field in rule_fields.items()
                if field in component
            )
            upstream: Set[FieldId] = set()
            downstream: Set[FieldId] = set()
            for left, right in edge_pairs:
                if left in component and right not in component:
                    other = right
                elif right in component and left not in component:
                    other = left
                else:
                    continue
                # Orientation of the canonical flow (upstream feeds
                # downstream) is recovered from the graph edges.
                flow = _flow_between(edge_pairs, left, right) if False else None
            events.append(component)  # placeholder replaced below

    # Rebuild events with proper neighbour orientation: build a directed
    # flow lookup once instead of per pair above.
    events = []
    flows = _directed_flows(edge_pairs, lineage_graph["edges"], clean_results)
    for sample_id in sorted(violations_by_sample):
        rule_fields = violations_by_sample[sample_id]
        fields = list(rule_fields.values())
        for component in _merge_components(fields, adjacent):
            rule_ids = sorted(
                rule_id
                for rule_id, field in rule_fields.items()
                if field in component
            )
            upstream: Set[FieldId] = set()
            downstream: Set[FieldId] = set()
            for left, right in edge_pairs:
                if left in component and right not in component:
                    inside, other = left, right
                elif right in component and left not in component:
                    inside, other = right, left
                else:
                    continue
                if flows[(inside, other)][0] == inside:
                    # inside feeds other -> other is downstream
                    downstream.add(other)
                else:
                    upstream.add(other)

            events.append(
                {
                    "sample_id": sample_id,
                    "rule_ids": rule_ids,
                    "fields": [
                        {"dataset_id": dataset_id, "field_id": field_id}
                        for dataset_id, field_id in sorted(component)
                    ],
                    "upstream_fields": [
                        {"dataset_id": dataset_id, "field_id": field_id}
                        for dataset_id, field_id in sorted(upstream)
                    ],
                    "downstream_fields": [
                        {"dataset_id": dataset_id, "field_id": field_id}
                        for dataset_id, field_id in sorted(downstream)
                    ],
                }
            )

    events.sort(key=lambda event: event["sample_id"])
    return {"events": events}


def _directed_flows(
    edge_pairs: Set[Tuple[FieldId, FieldId]],
    edges: List[Dict[str, Any]],
    _clean_results: Any,
) -> Dict[Tuple[FieldId, FieldId], Tuple[FieldId, FieldId]]:
    """Map each unordered edge pair to its directed ``(upstream, downstream)``
    field pair (the upstream field feeds the downstream field)."""
    flows: Dict[Tuple[FieldId, FieldId], Tuple[FieldId, FieldId]] = {}
    for edge in edges:
        source = (edge["source"]["dataset_id"], edge["source"]["field_id"])
        target = (edge["target"]["dataset_id"], edge["target"]["field_id"])
        pair = tuple(sorted((source, target)))
        if pair not in edge_pairs:
            continue
        if edge["type"] == "downstream":
            flow = (source, target)
        else:
            flow = (target, source)
        previous = flows.get(pair)
        if previous is None or previous != flow:
            flows[pair] = flow
    directed: Dict[Tuple[FieldId, FieldId], Tuple[FieldId, FieldId]] = {}
    for (left, right), flow in flows.items():
        directed[(left, right)] = flow
        directed[(right, left)] = flow
    return directed

