        remaining.remove(seed)
        component = {seed}
        queue = [seed]
        while queue:
            current = queue.pop()
            for nxt in adjacency.get(current, ()):
                if nxt in remaining:
                    remaining.remove(nxt)
                    component.add(nxt)
                    queue.append(nxt)
        components.append(component)
    return components


def _field_objects(fields: Set[FieldId]) -> List[Dict[str, str]]:
