                {
                    "sample_id": sample_id,
                    "rule_ids": rule_ids,
                    "fields": _field_objects(component),
                    "upstream_fields": _field_objects(upstream),
                    "downstream_fields": _field_objects(downstream),
                }
            )

    events.sort(key=lambda event: event["sample_id"])
    return {"events": events}

